28	    27	async function main() {
29	    28	  const server = createServer(createApp());
30	    29	  attachWebSocket(server);
31	    30	  // listen first so /healthz can say "not ready yet" (503) instead of refusing connections
32	    31	  server.listen(config.port, () => console.log(`server on http://localhost:${config.port}`));
33	    32	
34	    33	  await connectWithRetry();
35	    34	  state.ready = true;
36	    35	  startOutboxWorker(); // also picks up replies left unsent by an instance that died
37	    36	  console.log('ready');
