40	    39	  const stop = () => {
41	    40	    state.ready = false; // load balancer stops sending us traffic
42	    41	    stopOutboxWorker(); // stop claiming new send jobs
43	    42	    server.close(() => process.exit(0));
44	    43	    setTimeout(() => process.exit(0), 3000).unref();
45	    44	  };
46	    45	  process.on('SIGTERM', stop);
